  "teacher/Double_linked_list.py::Double_Linked_List.__get_item": "def __get_item(self, idx):\n    if idx < 0:\n        idx += self.size\n    if idx > self.size - 1 or idx < 0:\n        raise IndexError(\"out of range\")\n    if idx < self.size // 2:\n        cur = self.head\n        cur_idx = 0\n        while cur_idx != idx:\n            cur = cur.next\n            cur_idx += 1\n        return cur\n    else:\n        cur = self.tail\n        cur_idx = self.size - 1\n        while cur_idx != idx:\n            cur = cur.prev\n            cur_idx -= 1\n        return cur",
  "teacher/Double_linked_list.py::Double_Linked_List.__len__": "def __len__(self):\n    return self.size",
  "teacher/Double_linked_list.py::Double_Linked_List.append": "def append(self, val):\n    new_node = Node(val)\n    self.size += 1\n    if not self.head:\n        self.head = self.tail = new_node\n        return\n    self.tail.next = new_node\n    new_node.prev = self.tail\n    self.tail = self.tail.next",
  "teacher/Double_linked_list.py::Double_Linked_List.appendleft": "def appendleft(self, val):\n    new_node = Node(val)\n    self.size += 1\n    if not self.head:\n        self.head = self.tail = new_node\n        return\n    self.head.prev = new_node\n    new_node.next = self.head\n    self.head = new_node",
  "teacher/Double_linked_list.py::Double_Linked_List.reverse": "def reverse(self):\n    cur = self.head\n    while cur:\n        cur.prev, cur.next = cur.next, cur.prev\n        cur = cur.prev\n    self.head, self.tail = self.tail, self.head",
  "teacher/Double_linked_list.py::Double_Linked_List.insert": "def insert(self, idx, val):\n    if idx < 0:\n        idx += self.size\n    if idx < 0:\n        idx = 0\n    if idx > self.size:\n        idx = self.size\n\n    if idx == 0:\n        self.appendleft(val)\n    elif idx == self.size:\n        self.append(val)\n    else:\n        new_node = Node(val)\n        prev_node = self.__get_item(idx - 1)\n        next_node = prev_node.next\n\n        new_node.prev = prev_node\n        new_node.next = next_node\n        prev_node.next = new_node\n        if next_node:\n            next_node.prev = new_node\n\n        self.size += 1",
  "teacher/Double_linked_list.py::Double_Linked_List.pop": "def pop(self, idx=-1):\n    if self.size == 0:\n        raise IndexError(\"pop from empty list\")\n\n    if idx < 0:\n        idx += self.size\n    if idx < 0 or idx >= self.size:\n        raise IndexError(\"out of range\")\n\n    node = self.__get_item(idx)\n    val = node.val\n\n    prev_node = node.prev\n    next_node = node.next\n\n    if prev_node:\n        prev_node.next = next_node\n    else:\n        self.head = next_node\n\n    if next_node:\n        next_node.prev = prev_node\n    else:\n        self.tail = prev_node\n\n    self.size -= 1\n    return val",
  "teacher/Double_linked_list.py::Double_Linked_List.remove": "def remove(self, val):\n    cur = self.head\n    while cur:\n        if cur.val == val:\n            if cur.prev:\n                cur.prev.next = cur.next\n            else:\n                self.head = cur.next\n\n            if cur.next:\n                cur.next.prev = cur.prev\n            else:\n                self.tail = cur.prev\n\n            self.size -= 1\n            return\n        cur = cur.next\n\n    raise ValueError(f\"{val} not in list\")",
  "teacher/Double_linked_list.py::Double_Linked_List.find": "def find(self, val):\n    cur = self.head\n    idx = 0\n    while cur:\n        if cur.val == val:\n            return idx\n        cur = cur.next\n        idx += 1\n    return -1",
  "teacher/Double_linked_list.py::Double_Linked_List.__getitem__": "def __getitem__(self, idx):\n    return self.__get_item(idx).val",
  "teacher/Double_linked_list.py::Double_Linked_List.__setitem__": "def __setitem__(self, idx, value):\n    self.__get_item(idx).val = value",
  "teacher/Double_linked_list.py::Double_Linked_List.__iter__": "def __iter__(self):\n    cur = self.head\n    while cur:\n        yield cur.val\n        cur = cur.next",
  "teacher/Double_linked_list.py::Double_Linked_List.__str__": "def __str__(self):\n    if not self.head:\n        return \"empty\"\n    cur = self.head\n    res = \"\"\n    while cur:\n        if not cur.next:\n            res += f\"{cur.val}\"\n            cur = cur.next\n            continue\n        res += f\"{cur.val}⇔\"\n        cur = cur.next\n    return res",
  "teacher/Hash_set.py::Node": "class Node:\n    def __init__(self, key=None, val=None):\n        self.key = key\n        self.next = None",
