  "teacher/Hash_set.py::Hashset": "class Hashset:\n    def __init__(self, capacity = 10, load_factor = 0.75):\n        self.capacity = capacity\n        self.size = 0\n        self.buckets = [None] * self.capacity\n        self.load_factor = load_factor\n        \n    def __iter__(self):\n        for el in self.buckets:\n            while el:\n                yield el\n                el = el.next\n    \n    def __str__(self):\n        res = ''\n        count = 0\n        for el in self:\n            count += 1\n            if count == self.size:\n                res += f'{el.key}'\n                break\n            res += f'{el.key}, '\n        return '{' + res + '}'\n    \n        \n    def _hash(self, key):\n        if isinstance(key, str):\n            data = key.encode('utf-8')\n        else:\n            data = str(key).encode('utf-8')\n        \n        hash_val = 0x811c9dc5 \n        for byte in data:\n            hash_val ^= byte\n            hash_val *= 0x01000193  \n            hash_val &= 0xFFFFFFFF  \n        \n        return hash_val % self.capacity\n    \n    def _load_factor(self):\n        return self.size / self.capacity\n    \n    def _resize(self):\n        old_buckets = self.buckets\n        self.capacity *= 2\n        self.buckets = [None] * self.capacity\n        self.size = 0\n        for node in old_buckets:\n            while node:\n                self.add(node.key)\n                node = node.next\n    \n    def add(self, key):\n        if self._load_factor() >= self.load_factor:\n            self._resize()\n        idx = self._hash(key)\n        head = self.buckets[idx]\n        if head is None:\n            self.buckets[idx] = Node(key)\n            self.size += 1\n            return\n        while head:\n            if head.key == key:\n                return\n            prev = head\n            head = head.next\n        prev.next = Node(key)\n    \n    def remove(self, key):\n        idx = self._hash(key)\n        head = self.buckets[idx]\n        if head is None:\n            raise KeyError(\"no key\")\n        if head.key == key:\n            self.buckets[idx] = head.next\n            self.size -= 1\n            return\n        \n        while head:\n            if head.next.key == key:\n                head.next = head.next.next\n                self.size -= 1\n                return \n            head = head.next\n        raise KeyError(\"no key\")",
  "teacher/Hash_set.py::Hashset.__init__": "def __init__(self, capacity = 10, load_factor = 0.75):\n    self.capacity = capacity\n    self.size = 0\n    self.buckets = [None] * self.capacity\n    self.load_factor = load_factor",
  "teacher/Hash_set.py::Hashset.__iter__": "def __iter__(self):\n    for el in self.buckets:\n        while el:\n            yield el\n            el = el.next",
  "teacher/Hash_set.py::Hashset.__str__": "def __str__(self):\n    res = ''\n    count = 0\n    for el in self:\n        count += 1\n        if count == self.size:\n            res += f'{el.key}'\n            break\n        res += f'{el.key}, '\n    return '{' + res + '}'",
  "teacher/Hash_set.py::Hashset._hash": "def _hash(self, key):\n    if isinstance(key, str):\n        data = key.encode('utf-8')\n    else:\n        data = str(key).encode('utf-8')\n    \n    hash_val = 0x811c9dc5 \n    for byte in data:\n        hash_val ^= byte\n        hash_val *= 0x01000193  \n        hash_val &= 0xFFFFFFFF  \n    \n    return hash_val % self.capacity",
  "teacher/Hash_set.py::Hashset._load_factor": "def _load_factor(self):\n    return self.size / self.capacity",
