  "teacher/Hash_set.py::Hashset.add": "def add(self, key):\n    if self._load_factor() >= self.load_factor:\n        self._resize()\n    idx = self._hash(key)\n    head = self.buckets[idx]\n    if head is None:\n        self.buckets[idx] = Node(key)\n        self.size += 1\n        return\n    while head:\n        if head.key == key:\n            return\n        prev = head\n        head = head.next\n    prev.next = Node(key)",
  "teacher/Hash_set.py::Hashset.remove": "def remove(self, key):\n    idx = self._hash(key)\n    head = self.buckets[idx]\n    if head is None:\n        raise KeyError(\"no key\")\n    if head.key == key:\n        self.buckets[idx] = head.next\n        self.size -= 1\n        return\n    \n    while head:\n        if head.next.key == key:\n            head.next = head.next.next\n            self.size -= 1\n            return \n        head = head.next\n    raise KeyError(\"no key\")",
  "teacher/Hash_table.py::Node": "class Node:\n    def __init__(self, key=None, val=None):\n        self.key = key\n        self.val = val\n        self.next = None",
  "teacher/Hash_table.py::Node.__init__": "def __init__(self, key=None, val=None):\n    self.key = key\n    self.val = val\n    self.next = None",
  "teacher/Hash_table.py::Hashtable": "class Hashtable:\n    def __init__(self, capacity = 10, load_factor = 0.75):\n        self.capacity = capacity\n        self.size = 0\n        self.buckets = [None] * self.capacity\n        self.load_factor = load_factor\n\n    def _hash(self, key):\n        if isinstance(key, str):\n            data = key.encode('utf-8')\n        else:\n            data = str(key).encode('utf-8')\n        \n        hash_val = 0x811c9dc5 \n        for byte in data:\n            hash_val ^= byte\n            hash_val *= 0x01000193  \n            hash_val &= 0xFFFFFFFF  \n        \n        return hash_val % self.capacity\n\n    def _load_factor(self):\n        return self.size / self.capacity\n\n    def _resize(self):\n        old_buckets = self.buckets\n        self.capacity *= 2\n        self.buckets = [None] * self.capacity\n        self.size = 0\n        for node in old_buckets:\n            while node:\n                self[node.key] = node.val\n                node = node.next\n\n    def __setitem__(self, key, val):\n        if self._load_factor() >= self.load_factor:\n            self._resize()\n        head = self.buckets[self._hash(key)]\n        if head is None:\n            self.buckets[self._hash(key)] = Node(key, val)\n            self.size += 1\n            return\n\n        while head:\n            if head.key == key:\n                head.val = val\n                return\n            prev = head\n            head = head.next\n        prev.next = Node(key, val)\n        self.size += 1\n\n    def __getitem__(self, key):\n        head = self.buckets[self._hash(key)]\n        while head.next:\n            if head.key == key:\n                return head.val\n            head = head.next\n        raise KeyError(f'no key {key}')\n\n    def remove(self, key):\n        head = self.buckets[self._hash(key)]\n        if head is None:\n            raise KeyError(\"No key\")\n        if head.key == key:\n            self.buckets[self._hash(key)] = head.next\n            self.size -= 1\n            return\n        while head:\n            if head.next.key == key:\n                head.next = head.next.next\n                self.size -= 1\n                return\n        raise KeyError('No such key')\n            \n\n    def __len__(self):\n        return self.size\n    \n    def __str__(self):\n        res = \"\"\n        count = 0\n        for el in self:\n            count += 1\n            if count == self.size:\n                res += f'{el.key}:{el.val}'\n                break\n            res += f'{el.key}:{el.val}, '\n        return '{' + f'{res}' +'}'\n    def __iter__(self):\n        for head in self.buckets:\n            while head:\n                yield head\n                head = head.next\n\n    def keys(self):\n        res = []\n        for j in self:\n            res.append(j.keys)\n        return res\n\n    def values(self):\n        res = []\n        for j in self:\n            res.append(j.val)\n        return res\n\n    def items(self):\n        res = []\n        for j in self:\n            res.append((j.key, j.val))\n        return res",
  "teacher/Hash_table.py::Hashtable.__init__": "def __init__(self, capacity = 10, load_factor = 0.75):\n    self.capacity = capacity\n    self.size = 0\n    self.buckets = [None] * self.capacity\n    self.load_factor = load_factor",
  "teacher/Hash_table.py::Hashtable._hash": "def _hash(self, key):\n    if isinstance(key, str):\n        data = key.encode('utf-8')\n    else:\n        data = str(key).encode('utf-8')\n    \n    hash_val = 0x811c9dc5 \n    for byte in data:\n        hash_val ^= byte\n        hash_val *= 0x01000193  \n        hash_val &= 0xFFFFFFFF  \n    \n    return hash_val % self.capacity",
  "teacher/Hash_table.py::Hashtable._load_factor": "def _load_factor(self):\n    return self.size / self.capacity",
  "teacher/Hash_table.py::Hashtable._resize": "def _resize(self):\n    old_buckets = self.buckets\n    self.capacity *= 2\n    self.buckets = [None] * self.capacity\n    self.size = 0\n    for node in old_buckets:\n        while node:\n            self[node.key] = node.val\n            node = node.next",
  "teacher/Hash_table.py::Hashtable.__setitem__": "def __setitem__(self, key, val):\n    if self._load_factor() >= self.load_factor:\n        self._resize()\n    head = self.buckets[self._hash(key)]\n    if head is None:\n        self.buckets[self._hash(key)] = Node(key, val)\n        self.size += 1\n        return\n\n    while head:\n        if head.key == key:\n            head.val = val\n            return\n        prev = head\n        head = head.next\n    prev.next = Node(key, val)\n    self.size += 1",
  "teacher/Hash_table.py::Hashtable.__getitem__": "def __getitem__(self, key):\n    head = self.buckets[self._hash(key)]\n    while head.next:\n        if head.key == key:\n            return head.val\n        head = head.next\n    raise KeyError(f'no key {key}')",
  "teacher/Hash_table.py::Hashtable.remove": "def remove(self, key):\n    head = self.buckets[self._hash(key)]\n    if head is None:\n        raise KeyError(\"No key\")\n    if head.key == key:\n        self.buckets[self._hash(key)] = head.next\n        self.size -= 1\n        return\n    while head:\n        if head.next.key == key:\n            head.next = head.next.next\n            self.size -= 1\n            return\n    raise KeyError('No such key')",
  "teacher/Hash_table.py::Hashtable.__len__": "def __len__(self):\n    return self.size",
  "teacher/Hash_table.py::Hashtable.__str__": "def __str__(self):\n    res = \"\"\n    count = 0\n    for el in self:\n        count += 1\n        if count == self.size:\n            res += f'{el.key}:{el.val}'\n            break\n        res += f'{el.key}:{el.val}, '\n    return '{' + f'{res}' +'}'",
  "teacher/Hash_table.py::Hashtable.__iter__": "def __iter__(self):\n    for head in self.buckets:\n        while head:\n            yield head\n            head = head.next",
  "teacher/Hash_table.py::Hashtable.keys": "def keys(self):\n    res = []\n    for j in self:\n        res.append(j.keys)\n    return res",
  "teacher/Hash_table.py::Hashtable.values": "def values(self):\n    res = []\n    for j in self:\n        res.append(j.val)\n    return res",
