  "teacher/Heap.py::Heap": "class Heap:\n    def __init__(self):\n        self.heap = []\n        \n    def heapify(self):\n        pass\n    \n    def _compare(self, a, b) -> bool:\n        return a < b if self._is_min else a > b\n    \n    def _shift_up(self, i):\n        while i > 0:\n            parent = (i - 1) // 2\n            if self._compare(self._data[i], self._data[parent]):\n                self._data[i], self._data[parent] = self._data[parent], self._data[i]\n                i = parent\n            else:\n                break\n            \n    def heapify(self, items) -> None:\n        self._data = list(items)\n        for i in range(len(self._data) // 2 - 1, -1, -1):\n            self._sift_down(i)\n    \n    def _shift_down(self, i):\n        n = len(self.heap)\n        while True:\n            best = i\n            left = 2 * i + 1\n            right = 2 * i + 2\n\n            if left < n and self._compare(self.heap[left], self.heap[best]):\n                best = left\n            if right < n and self._compare(self.heap[right], self.heap[best]):\n                best = right\n\n            if best == i:\n                break\n            self.heap[i], self.heap[best] = self.heap[best], self.heap[i]\n            i = best\n    \n    def pop(self):\n        if not self.heap:\n            raise ValueError(\"Pop from empty heap\")\n        if not self.heap:\n            return\n        self.heap[0], self.heap[len(self.heap) - 1] = self.heap[len(self.heap) - 1], self.heap[0]\n        self.heap.pop()\n        self._shift_down(0)\n    \n    def append(self, val):\n        self._data.append(val)\n        self._sift_up(len(self._data) - 1)\n        \n    def peek(self):\n        if not self.heap:\n            raise ValueError(\"Peek from empty heap\")\n        return self.heap[0]",
  "teacher/Heap.py::Heap.__init__": "def __init__(self):\n    self.heap = []",
  "teacher/Heap.py::Heap.heapify": "def heapify(self, items) -> None:\n    self._data = list(items)\n    for i in range(len(self._data) // 2 - 1, -1, -1):\n        self._sift_down(i)",
  "teacher/Heap.py::Heap._compare": "def _compare(self, a, b) -> bool:\n    return a < b if self._is_min else a > b",
  "teacher/Heap.py::Heap._shift_up": "def _shift_up(self, i):\n    while i > 0:\n        parent = (i - 1) // 2\n        if self._compare(self._data[i], self._data[parent]):\n            self._data[i], self._data[parent] = self._data[parent], self._data[i]\n            i = parent\n        else:\n            break",
  "teacher/Heap.py::Heap._shift_down": "def _shift_down(self, i):\n    n = len(self.heap)\n    while True:\n        best = i\n        left = 2 * i + 1\n        right = 2 * i + 2\n\n        if left < n and self._compare(self.heap[left], self.heap[best]):\n            best = left\n        if right < n and self._compare(self.heap[right], self.heap[best]):\n            best = right\n\n        if best == i:\n            break\n        self.heap[i], self.heap[best] = self.heap[best], self.heap[i]\n        i = best",
  "teacher/Heap.py::Heap.pop": "def pop(self):\n    if not self.heap:\n        raise ValueError(\"Pop from empty heap\")\n    if not self.heap:\n        return\n    self.heap[0], self.heap[len(self.heap) - 1] = self.heap[len(self.heap) - 1], self.heap[0]\n    self.heap.pop()\n    self._shift_down(0)",
  "teacher/Heap.py::Heap.append": "def append(self, val):\n    self._data.append(val)\n    self._sift_up(len(self._data) - 1)",
  "teacher/Heap.py::Heap.peek": "def peek(self):\n    if not self.heap:\n        raise ValueError(\"Peek from empty heap\")\n    return self.heap[0]",
  "teacher/Linked_list.py::Node": "class Node:\n    def __init__(self, val):\n        self.val = val\n        self.next = None",
  "teacher/Linked_list.py::Node.__init__": "def __init__(self, val):\n    self.val = val\n    self.next = None",
  "teacher/Linked_list.py::Linked_list": "class Linked_list:\n    def __init__(self, *lst):\n        self.size = len(lst)\n        if not lst:\n            self.head = None\n            return\n        self.head = Node(lst[0])\n        cur = self.head\n        for i in range(1, len(lst)):\n            cur.next = Node(lst[i])\n            cur = cur.next\n\n    def __str__(self):\n        if not self.head:\n            return 'empty'\n        a = ''\n        cur = self.head\n        while cur:\n            if not cur.next:\n                a += f'{cur.val}'\n                return a\n            a += f'{cur.val}->'\n            cur = cur.next\n\n    def __len__(self):\n        return self.size\n\n    def is_empty(self):\n        return self.head is None\n\n    def _get_item(self, idx):\n        if idx < 0 or idx >= self.size:\n            raise IndexError(\"Index out of range\")\n        cur = self.head\n        cur_idx = 0\n        while cur_idx != idx:\n            cur = cur.next\n            cur_idx += 1\n        return cur\n\n    def __getitem__(self, idx):\n        target = self._get_item(idx)\n        return target.val\n\n    def append(self, val):\n        new_node = Node(val)\n        if self.head is None:\n            self.head = new_node\n        else:\n            cur = self.head\n            while cur.next:\n                cur = cur.next\n            cur.next = new_node\n        self.size += 1\n\n    def insert(self, idx, val):\n        if idx < 0 or idx > self.size:\n            raise IndexError(\"Index out of range\")\n\n        new_node = Node(val)\n\n        if idx == 0:\n            new_node.next = self.head\n            self.head = new_node\n        else:\n            prev = self._get_item(idx - 1)\n            new_node.next = prev.next\n            prev.next = new_node\n\n        self.size += 1\n\n    def remove(self, val):\n        if self.head is None:\n            raise ValueError(\"Value not found\")\n\n        if self.head.val == val:\n            self.head = self.head.next\n            self.size -= 1\n            return\n\n        cur = self.head\n        while cur.next is not None and cur.next.val != val:\n            cur = cur.next\n\n        if cur.next is None:\n            raise ValueError(\"Value not found\")\n\n        cur.next = cur.next.next\n        self.size -= 1\n\n    def pop(self, idx):\n        if idx < 0:\n            raise IndexError(\"Negative index is not allowed\")\n        if idx >= self.size:\n            raise IndexError(\"Index out of range\")\n\n        if idx == 0:\n            target = self.head\n            self.head = self.head.next\n            self.size -= 1\n            return target.val\n\n        cur = self.head\n        cur_idx = 0\n        while cur_idx != idx - 1:\n            cur = cur.next\n            cur_idx += 1\n\n        target = cur.next\n        cur.next = target.next\n        self.size -= 1\n        return target.val\n\n    def swap(self, idx1, idx2):\n        node1 = self._get_item(idx1)\n        node2 = self._get_item(idx2)\n        node1.val, node2.val = node2.val, node1.val\n\n    def reverse(self):\n        prev = None\n        cur = self.head\n        while cur:\n            nxt = cur.next\n            cur.next = prev\n            prev = cur\n            cur = nxt\n        self.head = prev\n\n    def __setitem__(self, idx, value):\n        target = self._get_item(idx)\n        target.val = value\n\n    def __iter__(self):\n        cur = self.head\n        while cur:\n            yield cur.val\n            cur = cur.next",
