  "teacher/Linked_list.py::Linked_list.remove": "def remove(self, val):\n    if self.head is None:\n        raise ValueError(\"Value not found\")\n\n    if self.head.val == val:\n        self.head = self.head.next\n        self.size -= 1\n        return\n\n    cur = self.head\n    while cur.next is not None and cur.next.val != val:\n        cur = cur.next\n\n    if cur.next is None:\n        raise ValueError(\"Value not found\")\n\n    cur.next = cur.next.next\n    self.size -= 1",
  "teacher/Linked_list.py::Linked_list.pop": "def pop(self, idx):\n    if idx < 0:\n        raise IndexError(\"Negative index is not allowed\")\n    if idx >= self.size:\n        raise IndexError(\"Index out of range\")\n\n    if idx == 0:\n        target = self.head\n        self.head = self.head.next\n        self.size -= 1\n        return target.val\n\n    cur = self.head\n    cur_idx = 0\n    while cur_idx != idx - 1:\n        cur = cur.next\n        cur_idx += 1\n\n    target = cur.next\n    cur.next = target.next\n    self.size -= 1\n    return target.val",
  "teacher/Linked_list.py::Linked_list.swap": "def swap(self, idx1, idx2):\n    node1 = self._get_item(idx1)\n    node2 = self._get_item(idx2)\n    node1.val, node2.val = node2.val, node1.val",
  "teacher/Linked_list.py::Linked_list.reverse": "def reverse(self):\n    prev = None\n    cur = self.head\n    while cur:\n        nxt = cur.next\n        cur.next = prev\n        prev = cur\n        cur = nxt\n    self.head = prev",
  "teacher/Linked_list.py::Linked_list.__setitem__": "def __setitem__(self, idx, value):\n    target = self._get_item(idx)\n    target.val = value",
  "teacher/Linked_list.py::Linked_list.__iter__": "def __iter__(self):\n    cur = self.head\n    while cur:\n        yield cur.val\n        cur = cur.next",
  "teacher/tree_dfs_bfs.py::inorder": "def inorder(root):\n    if not root:\n        return []\n    \n    # Лево + Корень + Право\n    return inorder(root.left) + [root.val] + inorder(root.right)",
  "teacher/tree_dfs_bfs.py::preorder": "def preorder(root):\n    if not root:\n        return []\n    \n    # Корень + Лево + Право\n    return [root.val] + preorder(root.left) + preorder(root.right)",
  "teacher/tree_dfs_bfs.py::postorder": "def postorder(root):\n    if not root:\n        return []\n    \n    # Лево + Право + Корень\n    return postorder(root.left) + postorder(root.right) + [root.val]",
  "teacher/tree_dfs_bfs.py::bfs_binary_tree": "def bfs_binary_tree(root):\n    if not root:\n        return []\n\n    result = []\n    queue = deque([root])\n\n    while queue:\n        node = queue.popleft()  # Извлекаем узел из головы очереди\n        result.append(node.val)\n\n        if node.left:\n            queue.append(node.left)\n        if node.right:\n            queue.append(node.right)\n\n    return result",
  "teacher/Trie.py::TrieNode": "class TrieNode:\n\n    def __init__(self):\n        self.children = {}\n        self.is_end = False",
  "teacher/Trie.py::TrieNode.__init__": "def __init__(self):\n    self.children = {}\n    self.is_end = False",
  "teacher/Trie.py::Trie": "class Trie:\n\n    def __init__(self):\n        self.root = TrieNode()\n\n    def insert(self, word):  # добавляет слово\n        node = self.root\n        for ch in word:\n            if ch not in node.children:\n                node.children[ch] = TrieNode()\n            node = node.children[ch]\n        node.is_end = True\n\n    def search(self, word):  # ищет слово\n        node = self.root\n        for ch in word:\n            if ch not in node.children:\n                return False\n            node = node.children[ch]\n        return node.is_end\n\n    def start_width(self, prefix):  # определяет есть ли слово с таким префиксом\n        node = self.root\n        for ch in prefix:\n            if ch not in node.children:\n                return False\n            node = node.children[ch]\n        return True\n\n    def delete(self, word):\n        if not self.search(word):\n            return False\n\n        def dfs_del(node, word, depth):\n            if depth == len(word):\n                node.is_end = False\n                return len(node.children) == 0\n            ch = word[depth]\n            child = node.children.get(ch)          \n            if child is None:                      \n                return False\n            delete_child = dfs_del(child, word, depth + 1)\n            if delete_child:\n                del node.children[ch]              # было: node.chldren[ch]\n                return (not node.is_end) and (len(node.children) == 0)\n            return False\n\n        dfs_del(self.root, word, 0)\n        return True",
  "teacher/Trie.py::Trie.__init__": "def __init__(self):\n    self.root = TrieNode()",
  "teacher/Trie.py::Trie.insert": "def insert(self, word):  # добавляет слово\n    node = self.root\n    for ch in word:\n        if ch not in node.children:\n            node.children[ch] = TrieNode()\n        node = node.children[ch]\n    node.is_end = True",
