  "teacher/Trie.py::Trie.start_width": "def start_width(self, prefix):  # определяет есть ли слово с таким префиксом\n    node = self.root\n    for ch in prefix:\n        if ch not in node.children:\n            return False\n        node = node.children[ch]\n    return True",
  "teacher/Trie.py::Trie.delete": "def delete(self, word):\n    if not self.search(word):\n        return False\n\n    def dfs_del(node, word, depth):\n        if depth == len(word):\n            node.is_end = False\n            return len(node.children) == 0\n        ch = word[depth]\n        child = node.children.get(ch)          \n        if child is None:                      \n            return False\n        delete_child = dfs_del(child, word, depth + 1)\n        if delete_child:\n            del node.children[ch]              # было: node.chldren[ch]\n            return (not node.is_end) and (len(node.children) == 0)\n        return False\n\n    dfs_del(self.root, word, 0)\n    return True"
